    "analysis": "【审题】题干：Eating alot of vegetables ____—_—s goood for your health。本句考查动名词作主语。\n【语法点/词汇】就近原则：either...or、neither...nor、not only...but also、there be 与最近的主语一致。就远原则：主语后接 with/together with/along with/as well as 时，谓语与真正的主语（前面的）一致。a set of / this pair of 作主语，谓语与 set/pair 一致（单数）。the number of（…的数量，谓语单数）；a number of（许多，谓语复数）。分数/百分数作主语，谓语与 of 后的名词一致。时间、金钱、距离作整体看待，谓语单数。here/there 引导的倒装句，谓语与后面的真正主语一致。动名词/不定式作主语，谓语单数。trousers 类复数名词用复数指代，但 a pair of 用单数。\n【步骤】① 定位考点：动名词作主语。② Eating vegetables 动名词作主语，用 is。 ③ 由此确定答案为 B。\n【答案】B. is\n【易错】动名词作主语视为整体，谓语单数。\n【口诀/模板句】就近：or/nor/there be；就远：with/along with；the number 单 a number 复；分数看名词；时间距离整体单；动名词主语用单数。"
