    "analysis": "【审题】题干：—Boys and girls, you should be thankful to those people helped and supported you. —We will. Miss Li。本句考查who 指人。\n【语法点/词汇】关系代词：who 指人（主格）、whom 指人（宾格）、whose 表所属、which 指物、that 指人或物。关系副词：where（地点）、when（时间）、why（原因）。关系副词 = 介词 + which（the house where = in which he was born）。只用 that 不用 which：先行词被最高级/序数词修饰、是不定代词（everything、anything、all、much）、被 the only/very 修饰、或人和物并列。非限制性定语从句（逗号后）不用 that；as 引导可放句首（As is reported）。介词后不用 that（in that 错，用 in which）。关系代词在从句中作宾语时可省略；从句中不能重复指代（that you bought it 错）。\n【步骤】① 定位考点：who 指人。② those people 指人，从句作主语用 who。 ③ 由此确定答案为 C。\n【答案】C. who\n【易错】helped 前缺主语，指人用 who；whom 作宾语。\n【口诀/模板句】人 who/whom 物 which，that 人物都能用；where=in which；最高级/不定代词/only 用 that；逗号后不用 that，介词后不接 that。"
